    /// <summary>Constuct new object</summary>
    /// <param name = "_args">Arguments</param>
    /// <param name = "_executionMode">Execution mode</param>
    /// <returns>New Controller Object</returns>
    public static SysOperationController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
    {
        METSalesOrderShipmentCreationControllerBatch controller = new METSalesOrderShipmentCreationControllerBatch();
        controller.parmExecutionMode(_executionMode);
        controller.parmArgs(_args);

        return controller;
    }

/// <summary>New object</summary>
protected void new()
{
    super(classstr(METSalesOrderShipmentCreationService), methodstr(METSalesOrderShipmentCreationService, runBatch), SysOperationExecutionMode::Synchronous);
}

/// <summary>Main method</summary>
